const students=()=>db.students.filter(s=>s.year===year&&s.role===role&&(!schoolFilter||s.school===schoolFilter)).sort((a,b)=>a.cls.localeCompare(b.cls,'ko')||a.number-b.number);const student=id=>db.students.find(s=>s.id===id);const inYear=r=>student(r.studentId)?.year===year&&student(r.studentId)?.role==='homeroom'&&(!schoolFilter||student(r.studentId)?.school===schoolFilter);const label=s=>s?`${s.number}번 ${s.name}`:'삭제된 학생';const sLink=id=>student(id)?.role==='subject'?`<span>${esc(label(student(id)))}</span>`:`<button class="link" data-action="profile" data-id="${esc(id)}">${esc(label(student(id)))}</button>`;const blank=s=>`<div class="empty">${s}</div>`;const badge=(s,cl='')=>`<span class="badge ${cl}">${esc(s)}</span>`;const overdue=d=>d&&d<today();const dateTag=d=>d?badge(`${d}${overdue(d)?' · 기한 지남':d===today()?' · 오늘':''}`,overdue(d)?'warn':''):'';const heading=(title,sub,button='')=>`<div class="heading"><div><h1>${title}</h1><div class="muted">${sub}</div></div>${button}</div>`;const add=(kind,text='새 기록')=>`<button class="primary" data-action="add" data-kind="${kind}">＋ ${text}</button>`;const editButtons=(kind,id)=>`<div class="actions"><button class="small" data-action="edit" data-kind="${kind}" data-id="${esc(id)}">수정</button><button class="small danger" data-action="delete" data-kind="${kind}" data-id="${esc(id)}">삭제</button></div>`;
function render(){document.body.dataset.page=page;updateFocus();let schools=db.schools.filter(x=>x.role===role&&x.name!=='학교 미지정').map(x=>x.name);if(!schools.includes(schoolFilter))schoolFilter=schools[0]||'__no_registered_school__';let bar=$('#schoolBar');if(!bar){bar=document.createElement('div');bar.id='schoolBar';bar.className='toolbar';$('.role-tabs').after(bar)}bar.innerHTML='<label>학교 선택<select id="schoolFilter">'+(!schools.length?'<option value="" disabled>학교를 먼저 등록하세요</option>':'')+schools.map(n=>'<option '+(schoolFilter===n?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select></label><button id="registerSchool" class="primary">＋ 학교 등록</button><button id="renameSchool" '+(!schoolFilter?'disabled':'')+'>학교 이름 수정</button><button id="deleteSchool" '+(!schoolFilter?'disabled':'')+'>학교 삭제</button><span class="muted">'+roleName()+' 전용 학교 목록</span>';  if(role==='subject')bar.querySelector('#deleteSchool').insertAdjacentHTML('afterend','<input id="teachingSubject" aria-label="교과" maxlength="150" placeholder="교과 입력" value="'+esc(db.teachingSubject||'')+'">');document.querySelectorAll('[data-action=role]').forEach(b=>{b.classList.toggle('active',b.dataset.role===role);b.setAttribute('aria-pressed',String(b.dataset.role===role))}); $('#year').innerHTML=[...db.years].sort((a,b)=>b-a).map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('');$('#nav').innerHTML=menu.filter(([p])=>['dashboard','backup','studio'].includes(p)||(role==='subject'?['students','assessments','subjectNotes'].includes(p):['students','notes','tasks'].includes(p))).map(([p,i,t])=>`<button data-action="nav" data-page="${p}" class="${page===p||page==='profile'&&p==='students'?'active':''}" ${page===p?'aria-current="page"':''}><span aria-hidden="true">${i}</span>${t}</button>`).join('');$('#view').innerHTML=(storageError?`<div class="notice" role="alert">${esc(storageError)}</div>`:'')+({dashboard:dashboard,students:studentPage,profile:profilePage,counsel:()=>recordPage('counsel'),contacts:()=>recordPage('contacts'),notes:noteWorkspace,assessments:assessmentPage,tasks:taskPage,subjectNotes:subjectNotePage,studio:studioPage,backup:backupPage}[page]());if(page==='dashboard')outsideDashboardTitles();afterCalendarRender();queueMicrotask(refreshPageFont);}
