function recordRow(r,k){return `<div class="row"><div>${sLink(r.studentId)} <span class="muted">${esc(r.date)}</span><div>${badge(r.category||r.method||r.subject||'성적')+(k==='contacts'&&r.category?' '+badge(r.method):'')}${k==='exams'?` <b>${esc(r.title)} · ${r.score} / ${r.max}점</b>`:''}</div>${r.title&&k==='notes'?`<h3>${esc(r.title)}</h3>`:''}${k==='notes'&&r.category==='출결'?badge(r.attendance||'미지정','amber'):''}<p>${esc(r.summary||r.note||'')}</p>${r.next?`<div class="muted">후속 일정 ${esc(r.next)} ${r.done?badge('완료'):badge(overdue(r.next)?'기한 지남':'대기',overdue(r.next)?'warn':'amber')} <button class="small" data-action="follow" data-kind="${k}" data-id="${esc(r.id)}">${r.done?'완료 취소':'후속 완료'}</button></div>`:''}</div>${editButtons(k,r.id)}</div>`}
function recordPage(k){let rs=db[k].filter(inYear).filter(r=>!recordFilter||r.studentId===recordFilter).sort((a,b)=>b.date.localeCompare(a.date));return heading(config[k].title,config[k].text,add(k))+`<div class="toolbar"><select id="recordFilter" aria-label="학생별 기록"><option value="">전체 학생</option>${students().map(s=>`<option value="${esc(s.id)}" ${recordFilter===s.id?'selected':''}>${esc(label(s))}</option>`).join('')}</select></div><section class="card">${rs.map(r=>recordRow(r,k)).join('')||blank('아직 기록이 없습니다. 새 기록을 남겨 보세요.')}</section>`}
