function submissionPage(){let as=db.assessments.filter(a=>a.year===year&&(!schoolFilter||a.school===schoolFilter));if(!as.some(a=>a.id===assessmentId))assessmentId=as[0]?.id||'';let a=as.find(a=>a.id===assessmentId),all=a?assessmentStudents(a):[],classSelector=gradeClassSelector(all),ss=all.filter(s=>!gradeClass||classKey(s)===gradeClass),ms=a?ss.filter(s=>result(a.id,s.id).status!=='제출'):[];return heading('수행평가 관리','제출 상태와 점수를 입력하면 확인 대상이 자동으로 모입니다.',add('assessments','평가 만들기'))+'<div class="toolbar">'+assessmentSelector()+classSelector+'</div>'+(a?`<section class="card"><div class="card-head"><div><h2>${esc(a.title)}</h2><span class="muted">${esc(scopeLabel(a))} · ${a.max}점 만점 · 마감 ${esc(a.due)}</span></div><div class="heading-buttons"><button id="copyAssessment">평가·루브릭 복제</button>${editButtons('assessments',a.id)}</div></div><div class="table-wrap"><table><thead><tr><th>학생</th><th>제출 상태</th><th>점수</th><th>만점</th></tr></thead><tbody>${ss.map(s=>{let r=result(a.id,s.id);return `<tr><td>${sLink(s.id)}</td><td><select data-result="status" data-student="${esc(s.id)}" aria-label="${esc(s.name)} 제출 상태">${['제출','미제출','재제출'].map(v=>`<option ${r.status===v?'selected':''}>${v}</option>`).join('')}</select></td><td><input type="number" min="0" max="${a.max}" step="0.1" data-result="score" data-student="${esc(s.id)}" aria-label="${esc(s.name)} 점수" value="${r.score??''}" ${r.status==='미제출'||a.criteria?.length?'disabled':''}></td><td>${a.max}</td></tr>`}).join('')}</tbody></table></div>${!ss.length?blank('평가 대상 학급에 학생이 없습니다.'):''}<p class="muted">변경 즉시 저장 · 루브릭 설정 시 점수는 학생별 채점에서 입력합니다. 미제출로 변경하면 해당 학생의 채점도 비워집니다.</p></section><section class="card"><h2>확인이 필요한 학생 <span class="badge">${ms.length}명</span></h2>${ms.map(s=>`<div class="row">${sLink(s.id)}${badge(result(a.id,s.id).status,'warn')}</div>`).join('')||blank('모든 학생이 제출했습니다.')}</section>`:blank('평가를 만들고 학생별 제출 상태를 관리해 보세요.'))}
function legacyTaskPage(){let ts=db.tasks.filter(t=>t.year===year&&taskRole(t)===role).sort((a,b)=>Number(a.done)-Number(b.done)||a.due.localeCompare(b.due));let groups=[['기한 지난 업무',t=>!t.done&&t.due<today()],['오늘',t=>!t.done&&t.due===today()],['다가오는 일정',t=>!t.done&&t.due>today()],['완료한 업무',t=>t.done]];return heading(roleName()+' 업무 일정','선택한 역할의 업무만 기한 순서대로 표시합니다.',add('tasks','업무 추가'))+groups.map(([title,test])=>`<section class="card"><h2>${title}</h2>${ts.filter(test).map(t=>`<div>${taskRow(t)}<div class="actions" style="justify-content:flex-end">${editButtons('tasks',t.id)}</div></div>`).join('')||blank('등록된 업무가 없습니다.')}</section>`).join('')}
function backupPage(){return fontSettingsHTML()+heading('데이터 관리','이 브라우저의 기록을 파일로 보관하고 다시 불러옵니다.')+`<section class="card"><h2>백업과 복원</h2><p class="backupStamp">${backupStamp()}</p><p class="muted">모든 학년도의 학생·기록·평가·업무·휴일과 글꼴 파일, 화면 설정, 삭제 복구함을 함께 백업합니다. 가져오기는 현재 데이터와 설정을 전체 교체합니다. 이전 형식의 백업도 불러올 수 있습니다.</p><div class="toolbar"><button class="primary" data-action="export">JSON 백업 내려받기</button><button data-action="import">JSON 백업 가져오기</button></div></section><section class="card"><h2>저장 안내</h2><p>주요 업무 자료는 Supabase에 자동 저장됩니다. 로그인 기능은 없으며, 화면 설정과 글꼴 등은 현재 브라우저에 저장됩니다.</p><p class="muted">브라우저 데이터 삭제·기기 변경 시 기록이 사라질 수 있습니다. 정기적으로 백업하세요. 주민등록번호, 주소, 연락처, 건강 정보 등 불필요한 민감 정보는 입력하지 마세요. 백업 파일에도 학생 기록이 포함됩니다.</p><p class="muted">HTML 파일을 다른 위치나 다른 브라우저에서 열면 기존 저장 데이터가 보이지 않을 수 있습니다. 이동 전 백업을 권장합니다.</p></section><section class="card"><h2>최근 삭제 복구</h2><p class="muted">최근 30회 삭제를 이 브라우저에 보관합니다. 예시 지우기·전체 초기화는 복구 대상이 아닙니다.</p><div id="trashList">${trashHTML()}</div></section><section class="card"><h2>초기화</h2><p class="muted">예시 데이터 지우기는 예시 학생과 그 학생에 연결된 기록, 예시 평가·업무를 삭제합니다. 직접 추가한 학생은 유지합니다.</p><div class="toolbar"><button data-action="clearDemo">예시 데이터 지우기</button><button class="danger" data-action="clearAll">전체 데이터 삭제</button></div></section>`}
