document.addEventListener('submit',async e=>{if(e.target.id!=='fontForm')return;e.preventDefault();let scope=fontEditingScope,name=$('#fontName').value.trim(),file=$('#fontFile').files[0],newId=null;try{let all=getFontPrefs(),old=editedFontPrefs(),prefs={...(name===(old.name||'Malgun Gothic')?old:{}),name:name||'Malgun Gothic',scale:Number($('#fontScale').value),line:Number($('#fontLine').value)};delete prefs.tabs;if(file){if(file.size>50*1024*1024)throw Error('50MB 이하 글꼴 파일을 선택하세요.');if(!/\.(woff2?|ttf|otf)$/i.test(file.name))throw Error('지원하는 글꼴 파일을 선택하세요.');let bytes=await file.arrayBuffer();await new FontFace('FontValidation',bytes).load();newId=uid();prefs.fontId=newId;prefs.fileName=file.name;delete prefs.data;await fontStore('put',newId,bytes)}let next=scope==='all'?{...prefs,tabs:all.tabs||{}}:{...all,tabs:{...all.tabs,[scope]:prefs}};localStorage.setItem(KEY+'_font',JSON.stringify(next));render();toast('선택한 범위의 글꼴 설정을 저장했습니다.')}catch(err){if(newId)await fontStore('delete',newId).catch(()=>{});if($('#fontError'))$('#fontError').textContent='적용 실패: '+err.message}});
