function outsideDashboardTitles(){
 const cards=[...document.querySelectorAll('#view > .grid > section.card, #view > section.card')];
 for(const card of cards){
 let header=card.querySelector(':scope > .card-head');
 if(!header){let title=card.querySelector(':scope > h2');if(!title)continue;header=document.createElement('div');header.className='card-head';header.appendChild(title);}
 const section=document.createElement('section');section.className='dashboard-section';card.before(section);section.append(header,card);header.classList.add('dashboard-section-title');
 }
}
function cleanDotText(root){
 if(!root||!(root instanceof Node))return;
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 for(const node of nodes){if(!node.nodeValue.includes('·')||node.parentElement?.closest('script,style,textarea,.sr-layout,#srDialog,#srCompareWindow,#srApiSettings,#srEvidenceWindow'))continue;let parent=node.parentElement;if(parent?.tagName==='OPTION'&&!parent.hasAttribute('value'))parent.setAttribute('value',parent.value);node.nodeValue=node.nodeValue.replace(/\s*·\s*/g,' ');}
}
const dotObserver=new MutationObserver(records=>{for(const r of records){if(r.type==='characterData'){if(r.target.nodeValue.includes('·'))cleanDotText(r.target.parentNode);}else for(const n of r.addedNodes){if(n.nodeType===1)cleanDotText(n);else if(n.nodeType===3&&n.nodeValue.includes('·'))cleanDotText(n.parentNode);}}});
dotObserver.observe(document.body,{subtree:true,childList:true,characterData:true});cleanDotText(document.body);

function zipTemplateFiles(files){
  const encoder=new TextEncoder(),locals=[],central=[];let offset=0;
  const make=(size)=>new Uint8Array(size),u16=(arr,at,n)=>new DataView(arr.buffer).setUint16(at,n,true),u32=(arr,at,n)=>new DataView(arr.buffer).setUint32(at,n>>>0,true);
  const crc32=data=>{let crc=0xffffffff;for(const byte of data){crc^=byte;for(let k=0;k<8;k++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}return (crc^0xffffffff)>>>0};
  for(const [path,xml] of files){
    const name=encoder.encode(path),data=xml,crc=crc32(data),local=make(30+name.length);
    u32(local,0,0x04034b50);u16(local,4,20);u16(local,10,0);u16(local,12,33);u32(local,14,crc);u32(local,18,data.length);u32(local,22,data.length);u16(local,26,name.length);local.set(name,30);
    const entry=make(46+name.length);u32(entry,0,0x02014b50);u16(entry,4,20);u16(entry,6,20);u16(entry,14,33);u32(entry,16,crc);u32(entry,20,data.length);u32(entry,24,data.length);u16(entry,28,name.length);u32(entry,42,offset);entry.set(name,46);
    locals.push(local,data);central.push(entry);offset+=local.length+data.length;
  }
  const centralSize=central.reduce((s,a)=>s+a.length,0),end=make(22);u32(end,0,0x06054b50);u16(end,8,files.length);u16(end,10,files.length);u32(end,12,centralSize);u32(end,16,offset);
  const out=make(offset+centralSize+end.length);let cursor=0;for(const chunk of [...locals,...central,end]){out.set(chunk,cursor);cursor+=chunk.length}return out;
}

let templateExportState=null;
async function readTemplateZip(buffer){let bytes=new Uint8Array(buffer),dv=new DataView(buffer),end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(dv.getUint32(i,true)===0x06054b50){end=i;break}if(end<0)throw Error('올바른 XLSX 파일이 아닙니다.');let count=dv.getUint16(end+10,true),pos=dv.getUint32(end+16,true),files=[];if(count>1000)throw Error('양식 파일이 너무 복잡합니다.');let total=0;for(let i=0;i<count;i++){if(dv.getUint32(pos,true)!==0x02014b50)throw Error('손상된 ZIP 구조입니다.');let method=dv.getUint16(pos+10,true),size=dv.getUint32(pos+20,true),rawSize=dv.getUint32(pos+24,true),nl=dv.getUint16(pos+28,true),ex=dv.getUint16(pos+30,true),co=dv.getUint16(pos+32,true),off=dv.getUint32(pos+42,true),name=new TextDecoder().decode(bytes.slice(pos+46,pos+46+nl));total+=rawSize;if(total>30000000)throw Error('압축 해제된 양식은 30MB 이하여야 합니다.');let start=off+30+dv.getUint16(off+26,true)+dv.getUint16(off+28,true),raw=bytes.slice(start,start+size);if(method===8)raw=new Uint8Array(await new Response(new Blob([raw]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());else if(method!==0)throw Error('지원하지 않는 압축 형식입니다.');files.push([name,raw]);pos+=46+nl+ex+co;}return files}
function templateXml(text){let doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror'))throw Error('양식 XML을 읽지 못했습니다.');return doc}
function templatePlan(files,a,cls){const dec=new TextDecoder(),map=new Map(files),sheetName='xl/worksheets/sheet1.xml';if(!map.has(sheetName))throw Error('첫 번째 시트가 없는 양식입니다.');let xml=dec.decode(map.get(sheetName)),doc=templateXml(xml),strings=map.has('xl/sharedStrings.xml')?[...templateXml(dec.decode(map.get('xl/sharedStrings.xml'))).getElementsByTagName('si')].map(n=>n.textContent):[];const cell=ref=>{let n=[...doc.getElementsByTagName('c')].find(n=>n.getAttribute('r')===ref);if(!n)return '';return n.getAttribute('t')==='s'?strings[Number(n.getElementsByTagName('v')[0]?.textContent)]||'':n.getAttribute('t')==='inlineStr'?n.textContent:n.getElementsByTagName('v')[0]?.textContent||''};if(cell('C1').trim()!=='반'||cell('D1').trim()!=='번호'||cell('E1').trim()!=='성명'||cell('J2').trim()!=='합계')throw Error('제공하신 양식과 열 구성이 다릅니다. C열 반, D열 번호, E열 성명, J열 합계를 확인하세요.');let max=cell('F1').match(/만점\s*:\s*([\d.]+)/);if(max&&Number(max[1])!==a.max)throw Error('양식 만점과 선택한 평가 만점이 다릅니다.');let classInfo=JSON.parse(cls),match=classInfo[1].match(/(?:^|\s)(\d+)\s*반/);if(!match)throw Error('학급 이름을 “3학년 1반”처럼 반 번호가 포함되게 등록하세요.');let roster=db.students.filter(s=>s.role==='subject'&&s.year===year&&classKey(s)===cls&&applies(a,s)),seen=new Set(),rows=[];for(let row of doc.getElementsByTagName('row')){let n=Number(row.getAttribute('r'));if(n<3)continue;let number=cell('D'+n).trim(),name=cell('E'+n).trim(),room=cell('C'+n).trim();if(!number&&!name)continue;let candidates=roster.filter(s=>s.number===Number(number)&&s.name.trim()===name),status='',score=null;if(Number(room)!==Number(match[1]))status='반 불일치';else if(seen.has(number))status='양식 번호 중복';else if(candidates.length!==1)status='번호 또는 성명 불일치';else{let g=gradeSummary(a,candidates[0]);if(g.complete){score=g.total;status='입력 가능'}else status='채점 미완료 (빈칸)'}seen.add(number);rows.push({row:n,number,name,status,score});}if(!rows.length)throw Error('양식에 학생 명단이 없습니다.');return {files,xml,sheetName,rows,assessmentId:a.id,cls};}
function openTemplateExport(){let as=db.assessments.filter(a=>a.year===year&&(!schoolFilter||a.school===schoolFilter));if(!as.length)return toast('평가를 먼저 등록하세요.');let d=$('#templateDialog');if(!d){d=document.createElement('dialog');d.id='templateDialog';d.style.width='min(760px,calc(100% - 28px))';document.body.appendChild(d)}d.innerHTML='<form id="templateForm"><h2>파일일괄등록 양식 내보내기</h2><p class="muted">평가 한 개의 학생별 확정 점수를 J열 합계에만 입력합니다. 양식의 명단·서식·다른 셀은 유지합니다. 미평가·채점 중인 학생의 합계는 비워 둡니다.</p><div class="fields">'+field('assessment','평가','select',assessmentId,{wide:true,options:as.map(a=>[a.id,a.title+' / '+scopeLabel(a)])})+field('class','학교와 학급','select','',{wide:true,options:[]})+'<label class="wide">원본 양식 XLSX<input id="templateFile" type="file" accept=".xlsx" required></label></div><div class="toolbar"><button id="templatePreview" type="button">학생 일치 확인</button></div><div id="templateMessage" role="status"></div><div id="templateRows" class="bulk-preview"></div><div class="form-actions"><button id="templateCancel" type="button">닫기</button><button id="templateDownload" class="primary" disabled>합계만 채워 내려받기</button></div></form>';templateExportState=null;const update=()=>{let a=as.find(a=>a.id===$('#f-assessment').value);$('#f-class').innerHTML=[...new Set(assessmentStudents(a).map(classKey))].map(c=>'<option value="'+esc(c)+'">'+esc(classCaption(c))+'</option>').join('');invalidate()};const invalidate=()=>{templateExportState=null;$('#templateDownload').disabled=true;$('#templateRows').innerHTML='';$('#templateMessage').textContent='양식을 선택하고 학생 일치 확인을 눌러 주세요.'};$('#f-assessment').onchange=update;$('#f-class').onchange=invalidate;$('#templateFile').onchange=invalidate;$('#templateCancel').onclick=()=>d.close();update();$('#templatePreview').onclick=async()=>{invalidate();let button=$('#templatePreview');button.disabled=true;try{let f=$('#templateFile').files[0],a=as.find(a=>a.id===$('#f-assessment').value),cls=$('#f-class').value;if(!f||!cls)throw Error('학급과 양식 파일을 선택하세요.');if(f.size>10000000)throw Error('10MB 이하 양식을 선택하세요.');let plan=templatePlan(await readTemplateZip(await f.arrayBuffer()),a,cls);if($('#f-assessment').value!==a.id||$('#f-class').value!==cls||$('#templateFile').files[0]!==f)return;plan.name=f.name;let bad=plan.rows.filter(r=>!['입력 가능','채점 미완료 (빈칸)'].includes(r.status)).length;$('#templateMessage').textContent=plan.rows.length+'명 확인 / 입력 가능 '+plan.rows.filter(r=>r.score!==null).length+'명 / 불일치 '+bad+'명';$('#templateRows').innerHTML='<table><thead><tr><th>번호</th><th>성명</th><th>확인</th><th>합계</th></tr></thead><tbody>'+plan.rows.map(r=>'<tr><td>'+esc(r.number)+'</td><td>'+esc(r.name)+'</td><td>'+r.status+'</td><td>'+(r.score??'빈칸')+'</td></tr>').join('')+'</tbody></table>';templateExportState=plan;$('#templateDownload').disabled=bad>0||!plan.rows.some(r=>r.score!==null);}catch(e){$('#templateMessage').textContent=e.message}finally{button.disabled=false}};$('#templateForm').onsubmit=e=>{e.preventDefault();try{let plan=templateExportState;if(!plan)return;let a=db.assessments.find(a=>a.id===plan.assessmentId),fresh=templatePlan(plan.files,a,plan.cls);if(fresh.rows.some(r=>!['입력 가능','채점 미완료 (빈칸)'].includes(r.status)))throw Error('명단이 변경되었습니다. 다시 확인하세요.');let xml=fresh.xml;for(let r of fresh.rows){let ref='J'+r.row,rx=new RegExp('<c\\b[^>]*\\br="'+ref+'"[^>]*(?:/>|>[\\s\\S]*?</c>)'),old=xml.match(rx)?.[0];if(!old)throw Error(ref+' 합계 셀을 찾지 못했습니다.');let tag=old.match(/^<c\b[^>]*>/)[0].replace(/\s+t="[^"]*"/,'').replace(/\s*\/>$/,'>');xml=xml.replace(rx,tag+(r.score===null?'':'<v>'+r.score+'</v>')+'</c>');}let out=zipTemplateFiles(fresh.files.map(([n,b])=>[n,n===fresh.sheetName?new TextEncoder().encode(xml):b])),url=URL.createObjectURL(new Blob([out],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})),link=document.createElement('a');link.href=url;link.download=plan.name.replace(/\.xlsx$/i,'_합계입력.xlsx');link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('합계만 채운 양식을 내려받았습니다.')}catch(e){$('#templateMessage').textContent=e.message}};d.showModal()}
document.addEventListener('click',e=>{if(e.target.closest('#templateExport'))openTemplateExport()});

let calendarDate=today(),calendarMonth=today().slice(0,7),calendarYearContext=year,holidayMemory={},holidayBusy={},holidayErrors={};
function calDate(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function taskScope(){return db.tasks.filter(t=>t.year===year&&taskRole(t)===role)}
function calTasks(date){return taskScope().filter(t=>t.due===date).sort((a,b)=>(a.time||'').localeCompare(b.time||'')||Number(a.done)-Number(b.done))}
function holidayCache(y){if(!holidayMemory[y]){try{let c=JSON.parse(localStorage.getItem(KEY+'_holidays_'+y)||'null');if(c&&Array.isArray(c.data))holidayMemory[y]=c}catch(e){}}return holidayMemory[y]}
function holidayOverrides(){try{return JSON.parse(localStorage.getItem(KEY+'_holidayOverrides')||'{}')}catch(e){return {}}}

const verifiedSubstitutes2026={'2026-03-02':'삼일절 대체공휴일','2026-05-25':'부처님오신날 대체공휴일','2026-08-17':'광복절 대체공휴일','2026-10-05':'개천절 대체공휴일'};
function visibleHolidayEntries(){return (db.holidayEntries||[]).filter(h=>h.kind!=='school'||h.role===role&&(!schoolFilter||(db.schools||[]).find(s=>s.id===h.schoolId)?.name===schoolFilter))}
function holidayNames(date){let custom=holidayOverrides()[date],names=custom?(custom.hidden?[]:[custom.name]):(holidayCache(Number(date.slice(0,4)))?.data||[]).filter(h=>h.date===date).map(h=>h.localName);if(!custom&&verifiedSubstitutes2026[date])names=[verifiedSubstitutes2026[date]];for(let h of visibleHolidayEntries().filter(h=>h.date===date)){let name=h.name+' ('+({temporary:'임시공휴일',substitute:'대체공휴일',school:'재량휴업일',public:'공휴일'}[h.kind])+')';if(h.kind==='school')name+=' '+((db.schools||[]).find(s=>s.id===h.schoolId)?.name||'삭제된 학교');names.push(name)}return [...new Set(names)]}
function holidayManager(id){let h=(db.holidayEntries||[]).find(h=>h.id===id),d=$('#holidayEditDialog');if(!d){d=document.createElement('dialog');d.id='holidayEditDialog';document.body.appendChild(d)}let schools=(db.schools||[]).filter(s=>s.role===role);d.innerHTML='<form id="holidayEditForm"><h2>공휴일과 학교 휴업일</h2>'+field('holidayDate','날짜','date',h?.date||calendarDate)+field('holidayKind','종류','select',h?.kind||'temporary',{options:[['temporary','임시공휴일'],['substitute','대체공휴일'],['school','재량휴업일'],['public','공휴일']]})+field('holidayName','이름','text',h?.name||'')+'<div id="holidaySchoolField">'+field('holidaySchool','적용 학교 ('+roleName()+')','select',h?.schoolId||schools.find(s=>s.name===schoolFilter)?.id||'',{required:false,options:[['','학교 선택'],...schools.map(s=>[s.id,s.name])]})+'</div><p class="muted">공휴일은 두 역할에 공통 적용됩니다. 재량휴업일은 현재 교사 역할의 선택한 학교에만 적용됩니다. 임시공휴일은 공식 지정된 날짜를 입력하세요.</p><div id="holidayEditError" class="error"></div><div class="form-actions"><button type="button" id="holidayEditCancel">닫기</button><button class="primary" type="submit">'+(h?'수정 저장':'등록')+'</button></div></form><h3>이 달 직접 등록한 휴일</h3><div>'+visibleHolidayEntries().filter(x=>x.date.startsWith(calendarMonth)).sort((a,b)=>a.date.localeCompare(b.date)).map(x=>'<div class="row"><span>'+esc(x.date+' '+x.name)+'<small> '+esc({temporary:'임시공휴일',substitute:'대체공휴일',school:'재량휴업일',public:'공휴일'}[x.kind])+'</small></span><span><button type="button" data-holiday-edit="'+esc(x.id)+'">수정</button> <button type="button" data-holiday-delete="'+esc(x.id)+'">삭제</button></span></div>').join('')+'</div><details><summary>기존 날짜 표시 보정</summary><p class="muted">선택 날짜 '+calendarDate+'의 자동 공휴일 표시만 조정합니다. 직접 등록한 휴일은 위 목록에서 삭제하세요.</p><button type="button" id="holidayHideAuto">자동 공휴일 숨기기</button> <button type="button" id="holidayResetAuto">자동 자료로 복원</button></details>';
let toggle=()=>{$('#holidaySchoolField').hidden=$('#f-holidayKind').value!=='school';$('#f-holidaySchool').required=$('#f-holidayKind').value==='school'};$('#f-holidayKind').onchange=toggle;toggle();$('#holidayEditCancel').onclick=()=>d.close();d.querySelectorAll('[data-holiday-edit]').forEach(b=>b.onclick=()=>holidayManager(b.dataset.holidayEdit));d.querySelectorAll('[data-holiday-delete]').forEach(b=>b.onclick=()=>{if(!confirm('이 휴일을 삭제할까요?'))return;let prev=db.holidayEntries;db.holidayEntries=prev.filter(x=>x.id!==b.dataset.holidayDelete);if(!save()){db.holidayEntries=prev;return}render();holidayManager()});for(let [bid,hide] of [['holidayHideAuto',true],['holidayResetAuto',false]])$('#'+bid).onclick=()=>{let overrides=holidayOverrides();if(hide)overrides[calendarDate]={name:'',hidden:true};else delete overrides[calendarDate];try{localStorage.setItem(KEY+'_holidayOverrides',JSON.stringify(overrides));render();toast('자동 공휴일 표시를 변경했습니다.')}catch(e){$('#holidayEditError').textContent='저장하지 못했습니다.'}};
$('#holidayEditForm').onsubmit=e=>{e.preventDefault();let kind=$('#f-holidayKind').value,date=$('#f-holidayDate').value,name=$('#f-holidayName').value.trim(),schoolId=kind==='school'?$('#f-holidaySchool').value:'',entry={id:h?.id||crypto.randomUUID(),date,name,kind,schoolId,role:kind==='school'?role:''};if(!name||name.length>150||!/^\d{4}-\d{2}-\d{2}$/.test(date)||kind==='school'&&!schools.some(s=>s.id===schoolId)){$('#holidayEditError').textContent='날짜, 이름(150자 이하), 적용 학교를 확인하세요.';return}let prev=db.holidayEntries||[];if(prev.some(x=>x.id!==entry.id&&x.date===date&&x.kind===kind&&x.schoolId===schoolId&&x.role===entry.role&&x.name===name)){$('#holidayEditError').textContent='이미 등록된 휴일입니다.';return}db.holidayEntries=[...prev.filter(x=>x.id!==entry.id),entry];if(!save()){db.holidayEntries=prev;$('#holidayEditError').textContent='저장하지 못했습니다.';return}calendarDate=date;calendarMonth=date.slice(0,7);d.close();render();toast('휴일을 저장했습니다.')};if(!d.open)d.showModal()}

async function loadCalendarHolidays(y,force=false){if(holidayBusy[y])return;let cache=holidayCache(y);if(!force&&cache&&Date.now()-Date.parse(cache.updated)<86400000)return;holidayBusy[y]=true;delete holidayErrors[y];updateHolidayStatus();try{let controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000),data;try{let response=await fetch('https://date.nager.at/api/v3/PublicHolidays/'+y+'/KR',{signal:controller.signal,cache:'no-store'});if(!response.ok)throw Error('연결 실패');data=await response.json()}finally{clearTimeout(timer)}if(!Array.isArray(data)||!data.length||data.some(h=>typeof h.localName!=='string'||!new RegExp('^'+y+'-\\d{2}-\\d{2}$').test(h.date)))throw Error('공휴일 자료 형식 오류');let item={data:data.filter(h=>!h.types||h.types.includes('Public')),updated:new Date().toISOString()};holidayMemory[y]=item;try{localStorage.setItem(KEY+'_holidays_'+y,JSON.stringify(item))}catch(e){holidayErrors[y]='이번 공휴일 자료는 저장하지 못해 현재 화면에서만 표시합니다.'}}catch(e){holidayErrors[y]=cache?'최신 자료 연결 실패. 이전에 저장한 공휴일을 표시합니다.':'공휴일 자료를 불러오지 못했습니다. 인터넷 연결 후 새로고침하세요. 2026년 확인된 대체공휴일과 직접 등록한 휴일만 표시합니다.'}finally{holidayBusy[y]=false;if(page==='tasks')render()}}
function updateHolidayStatus(){let el=$('#holidayStatus');if(!el)return;let y=Number(calendarMonth.slice(0,4)),cache=holidayCache(y);el.textContent=holidayBusy[y]?y+'년 대한민국 공휴일 확인 중…':holidayErrors[y]||(cache?y+'년 공휴일 갱신 '+new Date(cache.updated).toLocaleString('ko-KR'):'공휴일 자료 미수신');}
function calendarTaskPage(){if(calendarYearContext!==year){calendarYearContext=year;calendarMonth=year+'-03';calendarDate=calendarMonth+'-01'}let [y,m]=calendarMonth.split('-').map(Number),first=new Date(y,m-1,1),start=new Date(y,m-1,1-first.getDay()),selectedDate=new Date(calendarDate+'T12:00:00'),ts=calTasks(calendarDate),todayTasks=calTasks(today()).filter(t=>!t.done),now=new Date(),next=todayTasks.find(t=>t.time&&new Date(t.due+'T'+t.time)>now),cells='';for(let i=0;i<42;i++){let d=new Date(start);d.setDate(d.getDate()+i);let key=calDate(d),hs=holidayNames(key),tasks=calTasks(key),dow=d.getDay();cells+='<button class="cal-day '+(d.getMonth()!==m-1?'cal-outside ':'')+(key===calendarDate?'cal-selected ':'')+(key===today()?'cal-today ':'')+(dow===0||hs.length?'cal-holiday ':dow===6?'cal-saturday ':'')+'" data-cal-day="'+key+'" aria-pressed="'+(key===calendarDate)+'" aria-label="'+key+' '+esc(hs.join(' '))+' 업무 '+tasks.length+'건"><span class="cal-number">'+d.getDate()+'</span>'+hs.map(h=>'<span class="cal-holiday-label">'+esc(h)+'</span>').join('')+tasks.slice(0,2).map(t=>'<span class="cal-event '+(t.done?'cal-done':'')+'">'+esc((t.time||'종일')+' '+t.title)+'</span>').join('')+(tasks.length>2?'<span class="cal-more">+'+(tasks.length-2)+'건</span>':'')+'</button>'}
return heading(roleName()+' 업무 달력','날짜를 선택해 업무를 등록하고 시간을 확인하세요.','<div class="cal-clock"><span id="calendarClock"></span><small>현재 PC 시간</small></div>')+'<div class="cal-summary"><div><span class="muted">오늘 남은 업무</span><strong>'+todayTasks.length+'건</strong></div><div><span class="muted">'+(next?'다음 시간 일정':'오늘의 종일 업무')+'</span><strong>'+esc(next?next.time+' '+next.title:todayTasks.find(t=>!t.time)?.title||'예정된 업무가 없습니다.')+'</strong></div></div><div class="calendar-layout"><section class="calendar-panel"><div class="calendar-toolbar"><div><h2>'+y+'년 '+m+'월</h2><input id="calendarMonth" type="month" value="'+calendarMonth+'" aria-label="표시할 월"></div><div class="heading-buttons"><button data-cal-move="-1" aria-label="이전 달">‹</button><button id="calendarToday">오늘</button><button data-cal-move="1" aria-label="다음 달">›</button></div></div><div class="cal-week">'+['일','월','화','수','목','금','토'].map(t=>'<span>'+t+'</span>').join('')+'</div><div class="cal-grid">'+cells+'</div><div class="cal-footer">붉은 날짜: 일요일 또는 공휴일　녹색 표시: 오늘<br>현재 '+year+'학년도 '+roleName()+' 업무만 표시합니다.</div></section><section class="card calendar-agenda"><div class="card-head"><div><h2>'+selectedDate.toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long'})+'</h2><span class="muted">'+ts.length+'건</span></div><button class="primary" id="calendarAdd">＋ 업무 등록</button></div>'+holidayNames(calendarDate).map(h=>badge(h,'warn')).join(' ')+(ts.map(t=>'<div class="cal-agenda-item"><div class="muted">'+esc(t.time||'종일')+'</div>'+taskRow(t)+editButtons('tasks',t.id)+'</div>').join('')||blank('등록된 업무가 없습니다.'))+'</section></div><section class="card cal-sync"><div class="card-head"><h2>대한민국 공휴일</h2><div class="heading-buttons"><button id="calendarHolidayRefresh">공휴일 새로고침</button><button id="calendarHolidayEdit">공휴일 / 휴업일 관리</button></div></div><p id="holidayStatus" class="muted"></p><p class="muted">공휴일과 대체공휴일은 온라인 자료를 불러와 저장합니다. 2026년 대체공휴일 4일은 한국천문연구원 월력요항으로 보완합니다. 임시공휴일은 발표 후 자료 반영이 늦을 수 있어 직접 등록할 수 있습니다. 재량휴업일은 학교와 교사 역할별로 따로 등록하며, 직접 등록한 휴일은 JSON 백업에 포함됩니다.</p><a href="https://date.nager.at" target="_blank" rel="noopener" class="muted">공휴일 자료 출처</a></section>'}
function updateCalendarClock(){let el=$('#calendarClock');if(el)el.textContent=new Date().toLocaleTimeString('ko-KR',{hour12:false});}
function afterCalendarRender(){if(page!=='tasks')return;updateCalendarClock();updateHolidayStatus();let y=Number(calendarMonth.slice(0,4));if((!holidayCache(y)||Date.now()-Date.parse(holidayCache(y).updated)>86400000)&&!holidayErrors[y]&&!holidayBusy[y])setTimeout(()=>loadCalendarHolidays(y),0)}
setInterval(updateCalendarClock,1000);
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.calDay){calendarDate=b.dataset.calDay;calendarMonth=calendarDate.slice(0,7);render()}if(b.dataset.calMove){let [y,m]=calendarMonth.split('-').map(Number),d=new Date(y,m-1+Number(b.dataset.calMove),1);calendarMonth=calDate(d).slice(0,7);calendarDate=calendarMonth+'-01';render();loadCalendarHolidays(d.getFullYear())}if(b.id==='calendarToday'){calendarDate=today();calendarMonth=calendarDate.slice(0,7);render()}if(b.id==='calendarAdd'){openForm('tasks');$('#f-due').value=calendarDate;formBaseline=formSnapshot()}if(b.id==='calendarHolidayRefresh')loadCalendarHolidays(Number(calendarMonth.slice(0,4)),true);if(b.id==='calendarHolidayEdit')holidayManager()});
