function observationStudentGrade(s){return s.cls.match(/(\d+)\s*학년/)?.[1]||'미지정'}
function observationStudents(){return students().filter(s=>(!observationGrade||observationStudentGrade(s)===observationGrade)&&(!observationClass||classKey(s)===observationClass))}
function syncObservationFilters(){let context=year+'|'+schoolFilter;if(context!==observationContext){observationContext=context;observationGrade='';observationClass='';recordFilter=''}let ss=students();if(observationGrade&&!ss.some(s=>observationStudentGrade(s)===observationGrade))observationGrade='';if(observationClass&&!ss.some(s=>(!observationGrade||observationStudentGrade(s)===observationGrade)&&classKey(s)===observationClass))observationClass='';if(recordFilter&&!observationStudents().some(s=>s.id===recordFilter))recordFilter=''}
function observationFilterHTML(){let ss=students(),grades=[...new Set(ss.map(observationStudentGrade))].sort((a,b)=>a.localeCompare(b,'ko',{numeric:true})),classes=[...new Set(ss.filter(s=>!observationGrade||observationStudentGrade(s)===observationGrade).map(classKey))];return '<label>학년<select id="observationGrade"><option value="">전체 학년</option>'+grades.map(g=>'<option value="'+esc(g)+'" '+(g===observationGrade?'selected':'')+'>'+esc(g==='미지정'?'학년 미지정':g+'학년')+'</option>').join('')+'</select></label><label>반<select id="observationClass"><option value="">전체 반</option>'+classes.map(c=>'<option value="'+esc(c)+'" '+(c===observationClass?'selected':'')+'>'+esc(JSON.parse(c)[1])+'</option>').join('')+'</select></label>'}
function setupObservationPicker(){let studentSelect=$('#f-studentId'),current=student(studentSelect.value),ss=students(),g=current?observationStudentGrade(current):observationGrade,c=current?classKey(current):observationClass;let wrap=document.createElement('div');wrap.className='field wide observation-form-filters';wrap.innerHTML='<label>학년<select id="formObservationGrade" aria-label="관찰 학생 학년"></select></label><label>반<select id="formObservationClass" aria-label="관찰 학생 반"></select></label>';studentSelect.closest('.field').before(wrap);let gradeEl=$('#formObservationGrade'),classEl=$('#formObservationClass');gradeEl.innerHTML=[...new Set(ss.map(observationStudentGrade))].sort((a,b)=>a.localeCompare(b,'ko',{numeric:true})).map(x=>'<option value="'+esc(x)+'">'+esc(x==='미지정'?'학년 미지정':x+'학년')+'</option>').join('');gradeEl.value=g;
let updateStudents=(id)=>{let rows=ss.filter(s=>observationStudentGrade(s)===gradeEl.value&&classKey(s)===classEl.value);studentSelect.innerHTML=rows.map(s=>'<option value="'+esc(s.id)+'">'+esc(s.number+'번 '+s.name)+'</option>').join('');if(rows.some(s=>s.id===id))studentSelect.value=id};let updateClasses=(cls,id)=>{let classes=[...new Set(ss.filter(s=>observationStudentGrade(s)===gradeEl.value).map(classKey))];classEl.innerHTML=classes.map(k=>'<option value="'+esc(k)+'">'+esc(classCaption(k))+'</option>').join('');if(classes.includes(cls))classEl.value=cls;updateStudents(id)};gradeEl.onchange=()=>updateClasses();classEl.onchange=()=>updateStudents();updateClasses(c,current?.id);studentSelect.previousElementSibling.textContent='학생 이름';}
document.addEventListener('change',e=>{if(e.target.id==='observationGrade'){observationGrade=e.target.value;observationClass='';recordFilter='';render()}if(e.target.id==='observationClass'){observationClass=e.target.value;recordFilter='';render()}if(e.target.id==='teachingSubject'){let next={...db,teachingSubject:e.target.value.trim()};try{if(storageError)throw Error(storageError);persistData(JSON.stringify(next));db=next}catch(err){toast('교과 저장 실패: 입력을 유지합니다. 입력란에서 Enter를 눌러 재시도하세요.')}}});
