function srImportOriginal(){const d=srDraft(),dialog=srDialog();dialog.innerHTML='<h2>처음 받은 AI 초안 등록</h2><p class="muted">ChatGPT에서 처음 받은 문장을 붙여넣으세요. 현재 편집본은 바뀌지 않습니다.'+(d.originalText!==undefined?' 저장하면 기존 비교 원문이 교체됩니다.':'')+'</p><label for="srOriginalInput">비교할 AI 원문</label><textarea id="srOriginalInput" maxlength="100000">'+esc(d.originalText||'')+'</textarea><div id="srOriginalError" role="status"></div><div class="form-actions"><button id="srOriginalCancel">취소</button><button id="srOriginalSave" class="primary">비교 원문 저장</button></div>';$('#srOriginalCancel').onclick=()=>dialog.close();$('#srOriginalSave').onclick=()=>{const value=$('#srOriginalInput').value;if(!value.trim()){$('#srOriginalError').textContent='비교할 AI 원문을 붙여넣으세요.';return}const old={text:d.originalText,source:d.originalSource,at:d.originalAt};d.originalText=value;d.originalSource='직접 등록';d.originalAt=new Date().toISOString();if(!srSave(d)){if(old.text===undefined){delete d.originalText;delete d.originalSource;delete d.originalAt}else{d.originalText=old.text;d.originalSource=old.source;d.originalAt=old.at}$('#srOriginalError').textContent='저장하지 못했습니다. 입력을 유지합니다.';return}dialog.close();srRefreshComparison(d)};dialog.showModal()}
