function srCompareEditorHTML(d){return '<div class="sr-compare-bar"><span id="srCompareCounts"></span><span id="srCompareSave" role="status"></span></div><div id="srCompareMeter">'+srMeterHTML(d)+'</div><div class="sr-compare-grid sr-edit-grid"><section><div class="sr-pane-head"><h3>처음 AI 초안</h3><small>삭제: 붉은 취소선</small></div><div id="srCompareBefore" class="sr-diff-text"></div></section><section class="sr-current-pane"><div class="sr-pane-head"><h3><label for="srCompareEdit">현재 편집본</label></h3><button id="srToggleDiff" aria-pressed="false">변경 보기</button><button data-sr-api-settings aria-label="맞춤법 API 설정">API 설정</button><button id="srSpellCheck" title="현재 편집본 전체 맞춤법 검사">맞춤법 검사</button></div><div class="sr-edit-stack"><div id="srCompareAfter" aria-hidden="true"></div><textarea id="srCompareEdit" spellcheck="false" maxlength="100000" aria-label="현재 편집본">'+esc(d.text)+'</textarea></div><div id="srSpellPopover" hidden><div class="sr-pane-head"><strong>현재 편집본 맞춤법</strong><button id="srSpellClose" aria-label="맞춤법 결과 닫기">닫기</button></div><div id="srSpellResults" role="status"></div></div></section></div>'}
function srUpdateCompareWindow(d){
 const result=srDiff(d.originalText||'',d.text),parts=result.parts;
 $('#srCompareBefore').innerHTML=parts.filter(p=>p.kind!=='add').map(p=>p.kind==='del'?'<del>'+esc(p.text)+'</del>':esc(p.text)).join('')||'—';
 $('#srCompareAfter').innerHTML=parts.filter(p=>p.kind!=='del').map(p=>p.kind==='add'?'<ins>'+esc(p.text)+'</ins>':esc(p.text)).join('')||'';
 $('#srCompareCounts').textContent='· 추가 '+parts.filter(p=>p.kind==='add').reduce((n,p)=>n+Array.from(p.text).length,0)+'자 / 삭제 '+parts.filter(p=>p.kind==='del').reduce((n,p)=>n+Array.from(p.text).length,0)+'자'+(result.coarse?' (변경 구간 묶음)':'');
 $('#srCompareMeter').innerHTML=srMeterHTML(d);
 if($('#srCompareEdit').value!==d.text)$('#srCompareEdit').value=d.text;srSyncCompareScroll();
}
function srCommitCompare(d,text){d.text=text;d.status='draft';if($('#srText'))$('#srText').value=text;srRefreshComparison(d);srUpdateStatus(d);if($('#srMeter'))$('#srMeter').innerHTML=srMeterHTML(d);const saved=srSave(d);if($('#srCompareSave'))$('#srCompareSave').textContent=saved?'자동 저장됨':'저장하지 못했습니다. 입력 내용을 복사해 보관하세요.'}
function srBasicSpelling(text){
 const rules=[[/역활/g,'역할','표준 표기'],[/몇일/g,'며칠','표준 표기'],[/됬/g,'됐','되어의 준말'],[/되요/g,'돼요','되어요의 준말'],[/금새/g,'금세','금시에의 준말'],[/어의없/g,'어이없','표준 표기'],[/왠만/g,'웬만','표준 표기'],[/할수(?= 있| 없)/g,'할 수','의존 명사 띄어쓰기'],[/할 수 (있|없)는것/g,'할 수 $1는 것','의존 명사 띄어쓰기']];
 const suggestions=[];for(const [re,to,reason] of rules)for(const m of text.matchAll(re))suggestions.push({start:m.index,end:m.index+m[0].length,before:m[0],after:to.replace(/\$(\d+)/g,(_,n)=>m[Number(n)]||''),reason});
 return suggestions.sort((a,b)=>a.start-b.start).filter((x,i,a)=>!a.slice(0,i).some(y=>x.start<y.end));
}

function srSyncCompareScroll(){const edit=$('#srCompareEdit'),back=$('#srCompareAfter');if(edit&&back){back.scrollTop=edit.scrollTop;back.scrollLeft=edit.scrollLeft}}
function srSpellResult(d,snapshot,text,provider){const box=$('#srSpellResults');if(d.text!==snapshot){box.textContent='글이 변경되었습니다. 다시 검사하세요.';return}if(text===snapshot){box.textContent=provider+' 검사에서 수정 제안이 없습니다.';return}const parts=srDiff(snapshot,text).parts;box.innerHTML='<p>'+esc(provider)+' · 제안을 확인하고 적용하세요.</p><div class="sr-spell-preview">'+parts.map(p=>p.kind==='same'?esc(p.text):'<'+(p.kind==='del'?'del':'ins')+'>'+esc(p.text)+'</'+(p.kind==='del'?'del':'ins')+'>').join('')+'</div><button id="srSpellApplyAll" class="primary">전체 적용</button>';$('#srSpellApplyAll').onclick=()=>{if(d.text!==snapshot){box.textContent='글이 변경되었습니다. 다시 검사하세요.';return}srHistory(d,'맞춤법 수정 전');srCommitCompare(d,text);box.textContent='전체 적용했습니다. 이전 문장에서 되돌릴 수 있습니다.'}}
async function srRunSpelling(){
 const d=srDraft(),snapshot=d.text,box=$('#srSpellResults'),dialog=$('#srCompareWindow'),button=$('#srSpellCheck');$('#srSpellPopover').hidden=false;
 if(!snapshot.trim()){box.textContent='검사할 글을 입력하세요.';return}
 const config=srApiConfig();if(!config.bareun&&(!config.openai||!config.model)){box.innerHTML='<p>API 설정에서 바른 키 또는 OpenAI 키·모델을 입력하세요.</p><button data-sr-api-settings>API 설정 열기</button>';return}
 button.disabled=true;box.textContent='현재 편집본을 검사하고 있습니다…';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),120000),cancel=()=>controller.abort();dialog.addEventListener('close',cancel,{once:true});
 try{const bareun=config.spellProvider==='bareun'||config.spellProvider!=='openai'&&!!config.bareun;box.textContent=(bareun?'바른 맞춤법':'AI 맞춤법')+' 검사 중 · 현재 편집본만 전송합니다.';const j=await srDirectRequest(bareun?'spellcheck':'proofread',snapshot,controller.signal);if(typeof j.text!=='string'||!j.text.trim())throw Error('검사 결과가 비어 있습니다.');if(dialog.open)srSpellResult(d,snapshot,j.text,bareun?'바른 맞춤법':'AI 맞춤법');
 }catch(e){if(dialog.open)box.textContent=e.name==='AbortError'?'검사를 취소했거나 시간이 초과되었습니다.':e.message}finally{clearTimeout(timer);dialog.removeEventListener('close',cancel);button.disabled=false}
}
