function srTemplates(){return db.commonPrompts??=[]}
function srValidateTemplates(data){const list=data.commonPrompts||[];if(!Array.isArray(list)||list.length>100)throw Error('공통 프롬프트 형식 오류');const ids=new Set();for(const t of list){if(!t||typeof t.id!=='string'||!/^custom-[a-z0-9-]+$/.test(t.id)||ids.has(t.id)||typeof t.name!=='string'||t.name.length>100||typeof t.text!=='string'||t.text.length>20000)throw Error('공통 프롬프트 형식 오류');ids.add(t.id)}return list}
function srCommonEditor(isNew=false){if(srBusy)return;const dialog=srDialog();if(dialog.open)dialog.close();const id=srDraft().promptVariant,t=isNew?null:srTemplates().find(t=>t.id===id);dialog.innerHTML='<h2>공통 프롬프트 편집</h2><p>학생 기록을 넣지 않고 작성 지침만 저장하세요. 선택한 학생의 관찰 근거만 자동으로 붙습니다. 문체·분량 등 필요한 조건은 여기에 직접 작성하세요.</p><label>이름<input id="srCommonName" maxlength="100"></label><label>공통 작성 지침<textarea id="srCommonText" maxlength="20000" placeholder="예: 관찰된 행동부터 서술하고 추상적인 칭찬은 줄여 주세요."></textarea></label><div id="srCommonStatus" role="status"></div><div class="sr-toolbar"><button id="srCommonBack">돌아가기</button><button id="srCommonNew" class="primary">저장</button>'+'</div>';$('#srCommonName').value=t?.name||'';$('#srCommonText').value=t?.text||'';const persist=replace=>{const name=$('#srCommonName').value.trim(),text=$('#srCommonText').value.trim();if(!name||!text){$('#srCommonStatus').textContent='이름과 작성 지침을 입력하세요.';return}const previous=structuredClone(srTemplates()),d=srDraft(),old=d.promptVariant,newId=replace?t.id:'custom-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);if(!replace&&previous.length>=100){$('#srCommonStatus').textContent='공통 프롬프트는 100개까지 저장할 수 있습니다.';return}if(replace)Object.assign(t,{name,text});else srTemplates().push({id:newId,name,text});d.promptVariant=newId;if(!srSave(d)){db.commonPrompts=previous;d.promptVariant=old;$('#srCommonStatus').textContent='저장에 실패했습니다.';return}dialog.close();srPrepare()};$('#srCommonBack').onclick=()=>{dialog.close();srPrepare()};$('#srCommonNew').onclick=()=>persist(!!t);dialog.showModal()}
function srOverview(){const dialog=srDialog(),list=students().filter(s=>!srClass||classKey(s)===srClass);dialog.innerHTML='<h2>학급 작성 현황</h2><p>현재 학급'+(role==='subject'?' · '+esc(srSubject):'')+' / 기록 부족은 사용할 관찰기록이 없는 경우입니다.</p><div class="sr-stack">'+list.map(s=>'<button data-sr-go="'+esc(s.id)+'">'+esc(label(s))+' · '+srRosterState(s)+'</button>').join('')+'</div><button id="srOverviewClose">닫기</button>';$('#srOverviewClose').onclick=()=>dialog.close();dialog.querySelectorAll('[data-sr-go]').forEach(b=>b.onclick=()=>{srStudent=b.dataset.srGo;dialog.close();render()});dialog.showModal()}
function srEvidence(useOriginal=false){const d=srDraft(),records=useOriginal?(d.basis||[]):srChosen(d),sentences=(d.text.match(/[^.!?\n]+[.!?]?/g)||[]).map(s=>s.trim()).filter(Boolean);let dialog=$('#srEvidenceWindow');if(!dialog){dialog=document.createElement('dialog');dialog.id='srEvidenceWindow';dialog.setAttribute('aria-label','문장별 근거 확인');document.body.appendChild(dialog)}dialog.innerHTML='<div class="sr-pane-head"><h2>문장별 근거 확인</h2><button id="srEvidenceClose">닫기</button></div><p class="sr-meta">왼쪽 문장을 선택하면 오른쪽에 현재 선택한 관찰기록을 보여줍니다. 단어 일치는 참고용이며 근거의 타당성을 판정하지 않습니다.</p><div class="sr-toolbar"><button id="srEvidenceCurrent">현재 선택 근거</button><button id="srEvidenceOriginal">작성 당시 근거</button></div><p class="sr-meta">'+(useOriginal?'작성 당시 저장된 근거 사본 · 문장별 확정 연결은 아닙니다.':'현재 선택 근거 · 초안 작성 이후 달라졌을 수 있습니다.')+' </p><div class="sr-evidence-layout"><nav aria-label="초안 문장 목록">'+sentences.map((s,i)=>'<button data-evidence-sentence="'+i+'"><small>문장 '+(i+1)+'</small><span>'+esc(s)+'</span></button>').join('')+'</nav><section id="srEvidenceRecords"></section></div>';const choose=i=>{dialog.querySelectorAll('[data-evidence-sentence]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.evidenceSentence)===i);b.setAttribute('aria-pressed',String(Number(b.dataset.evidenceSentence)===i))});const words=[...new Set(sentences[i].match(/[가-힣A-Za-z0-9]{2,}/g)||[])],ranked=records.map(r=>({r,hits:words.filter(w=>r.text.includes(w))})).sort((a,b)=>b.hits.length-a.hits.length),hits=ranked.filter(x=>x.hits.length),others=ranked.filter(x=>!x.hits.length);const card=({r,hits})=>'<article class="sr-evidence-card"><small>'+esc(r.date)+'</small><h3>'+esc(r.title)+'</h3><p>'+esc(r.text)+'</p>'+(hits.length?'<div class="sr-meta">겹치는 단어: '+hits.map(esc).join(' · ')+'</div>':'')+'</article>';$('#srEvidenceRecords').innerHTML='<blockquote>'+esc(sentences[i])+'</blockquote><h3>관련 단어가 있는 기록 · '+hits.length+'건</h3>'+(hits.length?hits.map(card).join(''):'<p class="sr-note">일치하는 기록이 없습니다. 아래 전체 근거를 확인하세요.</p>')+(others.length?'<details '+(!hits.length?'open':'')+'><summary>나머지 선택 근거 '+others.length+'건 보기</summary>'+others.map(card).join('')+'</details>':'')+(!records.length?'<p>선택된 관찰 근거가 없습니다. 작성실에서 기록을 선택하세요.</p>':'')};dialog.querySelectorAll('[data-evidence-sentence]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.evidenceSentence)));$('#srEvidenceClose').onclick=()=>dialog.close();$('#srEvidenceCurrent').onclick=()=>{dialog.close();srEvidence(false)};$('#srEvidenceOriginal').onclick=()=>{dialog.close();srEvidence(true)};if(sentences.length)choose(0);else $('#srEvidenceRecords').textContent='작성된 문장이 없습니다.';dialog.showModal()}
let srDeletedCommon=null;
function srDeleteCommon(id){const oldTemplates=structuredClone(srTemplates()),oldDrafts=structuredClone(db.reportDrafts);db.commonPrompts=srTemplates().filter(t=>t.id!==id);for(const d of db.reportDrafts){if(d.promptVariant===id)d.promptVariant='1';if(d.promptEdits)delete d.promptEdits[id]}if(!save()){db.commonPrompts=oldTemplates;db.reportDrafts=oldDrafts;return false}srDeletedCommon={template:oldTemplates.find(t=>t.id===id),drafts:oldDrafts.map(d=>({id:d.id,variant:d.promptVariant,edit:d.promptEdits?.[id]}))};return true}
function srSpellChanges(before,after){let offset=0,group=null;const out=[];for(const p of srDiff(before,after).parts){if(p.kind==='same'){if(group){out.push(group);group=null}offset+=p.text.length}else{group??={start:offset,before:'',after:''};if(p.kind==='del'){group.before+=p.text;offset+=p.text.length}else group.after+=p.text}}if(group)out.push(group);return out}
function srSpellResult(d,snapshot,text,provider,target){const box=target||$('#srSpellResults');if(d.text!==snapshot){box.textContent='글이 변경되었습니다. 다시 검사하세요.';return}const changes=srSpellChanges(snapshot,text);if(!changes.length){box.textContent=provider+' 검사에서 수정 제안이 없습니다.';return}const selected=new Set(changes.map((_,i)=>i));box.innerHTML='<p>'+esc(provider)+' · 반영할 수정만 선택하세요.</p>'+changes.map((x,i)=>'<label class="sr-spell-item"><input type="checkbox" data-spell-choice="'+i+'" checked><span>'+esc(snapshot.slice(Math.max(0,x.start-12),x.start))+' <del>'+esc(x.before||'(삽입)')+'</del> → <ins>'+esc(x.after||'(삭제)')+'</ins> '+esc(snapshot.slice(x.start+x.before.length,x.start+x.before.length+12))+'</span></label>').join('')+'<button id="srSpellSelected">선택 적용</button><button id="srSpellApplyAll">전체 적용</button>';box.querySelectorAll('[data-spell-choice]').forEach(b=>b.onchange=()=>{const i=Number(b.dataset.spellChoice);b.checked?selected.add(i):selected.delete(i)});const apply=all=>{if(d.text!==snapshot){box.textContent='글이 변경되었습니다. 다시 검사하세요.';return}if(!all&&!selected.size)return;let result=snapshot;for(let i=changes.length-1;i>=0;i--)if(all||selected.has(i)){const x=changes[i];result=result.slice(0,x.start)+x.after+result.slice(x.start+x.before.length)}srHistory(d,'맞춤법 수정 전');srCommitCompare(d,result);box.innerHTML='<p>수정했습니다.</p><button id="srSpellUndo">방금 수정 되돌리기</button>';box.querySelector('#srSpellUndo').onclick=()=>{if(d.text!==result){box.textContent='이후 편집한 내용이 있습니다. 이전 문장에서 복원하세요.';return}srCommitCompare(d,snapshot);box.textContent='수정 전으로 되돌렸습니다.'}};box.querySelector('#srSpellSelected').onclick=()=>apply(false);box.querySelector('#srSpellApplyAll').onclick=()=>apply(true)}
