const srUndoStates=new Map();
function srUndoState(d){let v=srUndoStates.get(d.id);if(!v){v={past:[],future:[],current:d.text};srUndoStates.set(d.id,v)}return v}
function srRememberEdit(d,next){const v=srUndoState(d);if(v.current===next)return;v.past.push(v.current);if(v.past.length>80)v.past.shift();v.future=[];v.current=next}
const srOldCommit=srCommitCompare;srCommitCompare=function(d,text){srRememberEdit(d,text);srOldCommit(d,text)};
document.addEventListener('beforeinput',e=>{if(e.target.id==='srText'||e.target.id==='srCompareEdit')srUndoState(srDraft())},true);
document.addEventListener('input',e=>{if(e.target.id==='srText')srRememberEdit(srDraft(),e.target.value);if(e.target.id==='srStudentSearch'){const q=e.target.value.trim().toLowerCase();document.querySelectorAll('[data-sr-student]').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q))}});
function srStepStudent(step){const list=students().filter(s=>!srClass||classKey(s)===srClass),i=list.findIndex(s=>s.id===srStudent),next=list[i+step];if(next){srStudent=next.id;render()}else toast(step>0?'마지막 학생입니다.':'첫 학생입니다.')}
async function srDockSpell(){const d=srDraft(),snapshot=d.text,box=$('#srDockSpellResults'),button=$('#srDockSpell'),c=srApiConfig();if(!snapshot.trim()){box.textContent='검사할 글을 입력하세요.';return}const bareun=c.spellProvider==='bareun'||c.spellProvider!=='openai'&&!!c.bareun,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),120000);button.disabled=true;box.textContent='검사 중입니다. 현재 글을 '+(bareun?'바른':'OpenAI')+'으로 전송합니다.';try{const result=await srDirectRequest(bareun?'spellcheck':'proofread',snapshot,controller.signal,c);if(!box.isConnected)return;srSpellResult(d,snapshot,result.text,bareun?'바른':'OpenAI',box)}catch(e){if(box.isConnected)box.textContent=e.name==='AbortError'?'검사 시간이 초과되었습니다.':e.message}finally{clearTimeout(timer);button.disabled=false}}
