document.addEventListener('click',e=>{
 if(!e.target.closest('#connectLegacySchool'))return;
 if(!db.schools.some(s=>s.role===role&&s.name===schoolFilter&&s.name!=='학교 미지정'))return;
 const legacy=db.students.filter(s=>s.role===role&&(!s.school||s.school==='학교 미지정'));
 if(legacy.some(s=>db.students.some(t=>t.id!==s.id&&t.role===role&&t.school===schoolFilter&&t.year===s.year&&t.cls===s.cls&&t.number===s.number))){toast('선택 학교에 같은 학년도·학급·번호가 있어 연결하지 않았습니다. 명단을 확인해 주세요.');return;}
 if(!confirm('기존 미연결 자료를 '+schoolFilter+'에 연결할까요? 학생 ID와 연결된 기록·초안은 유지됩니다.'))return;
 const next=JSON.parse(JSON.stringify(db));
 next.students.forEach(s=>{if(s.role===role&&(!s.school||s.school==='학교 미지정'))s.school=schoolFilter;});
 if(role==='subject')next.assessments.forEach(a=>{if(!a.school||a.school==='학교 미지정')a.school=schoolFilter;});
 try{if(storageError)throw Error(storageError);persistData(JSON.stringify(next));db=next;render();toast('기존 자료를 학교에 연결했습니다.');}catch(err){toast('학교 연결을 저장하지 못했습니다.');}
});
