(()=>{
 let frame=0,serial=0;const measure=document.createElement('canvas').getContext('2d');
 function refresh(){frame=0;
  for(const select of document.querySelectorAll('select')){
   if(select.multiple||select.size>1)continue;
   if(!select.id)select.id='readable-select-'+(++serial);
   let full=document.getElementById(select.id+'-full-selection');
   if(!select.getClientRects().length){if(full&&!full.hidden)full.hidden=true;continue;}
   const style=getComputedStyle(select),text=select.selectedOptions[0]?.textContent?.trim()||'';
   measure.font=style.font;const spacing=parseFloat(style.letterSpacing)||0;
   const needed=measure.measureText(text).width+Math.max(0,Math.max(0,text.length-1)*spacing)+parseFloat(style.paddingLeft)+parseFloat(style.paddingRight)+26;
   const clipped=text&&needed>select.getBoundingClientRect().width+1;
   if(clipped){
    if(!full){full=document.createElement('span');full.id=select.id+'-full-selection';full.className='select-full-value';select.after(full);const ids=(select.getAttribute('aria-describedby')||'').split(' ').filter(Boolean);if(!ids.includes(full.id))ids.push(full.id);select.setAttribute('aria-describedby',ids.join(' '));}
    if(full.textContent!==text)full.textContent=text;if(full.hidden)full.hidden=false;
   }else if(full&&!full.hidden)full.hidden=true;
  }
 }
 const schedule=()=>{if(!frame)frame=requestAnimationFrame(refresh);};
 new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true,characterData:true});
 addEventListener('resize',schedule);document.addEventListener('change',schedule);document.fonts.addEventListener('loadingdone',schedule);document.fonts.ready.then(schedule);schedule();
})();

/* Workflow features: backup status, roster review, continuous entry, view memory. */
const workflowStore={read(key,fallback){try{return JSON.parse(localStorage.getItem(KEY+key))??fallback}catch{return fallback}},write(key,value){try{localStorage.setItem(KEY+key,JSON.stringify(value))}catch{}}};
function backupHealth(){const at=localStorage.getItem(KEY+'_backupAt'),days=at?Math.floor((Date.now()-Date.parse(at))/86400000):null;return{at,days,due:days===null||!Number.isFinite(days)||days>=7};}
function paintBackupHealth(){
 const old=$('#backupHealth');if(old)old.remove();const info=backupHealth();
 if(page!=='backup')return;
 const box=document.createElement('section');box.id='backupHealth';box.className='workflow-backup '+(info.due?'needs-backup':'');
 box.innerHTML='<div><strong>'+(info.due?'자료 백업을 확인해 주세요':'최근 백업 요청 기록')+'</strong><p>'+(info.at?'마지막 다운로드 요청: '+esc(new Date(info.at).toLocaleString('ko-KR')):'아직 백업 다운로드 요청 기록이 없습니다.')+' · 다운로드한 파일이 보관되어 있는지 확인해 주세요.</p></div><button data-action="export" class="'+(info.due?'primary':'')+'">전체 백업 받기</button>';
 const anchor=page==='backup'?$('#settings-data'):$('#view');anchor.prepend(box);
}
const workflowExport=exportFullBackup;
exportFullBackup=async function(){await workflowExport();paintBackupHealth();};

// Warn about gaps only within the known range; withdrawn students may legitimately leave gaps.
function rosterWarnings(rows){const groups=new Map();for(const r of rows){if(r.error||!Number.isInteger(r.number))continue;const key=r.cls;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}const out=[];
 for(const [cls,list] of groups){const numbers=new Set(list.map(r=>r.number)),max=Math.max(...numbers),gaps=[];for(let n=1;n<=max;n++)if(!numbers.has(n))gaps.push(n);const counts=new Map();list.forEach(r=>counts.set(r.name,(counts.get(r.name)||0)+1));const names=[...counts].filter(([,n])=>n>1).map(([name])=>name);if(gaps.length||names.length)out.push({cls,gaps,names});}return out;
}
const workflowPreview=previewBulk;
previewBulk=function(){workflowPreview();$('#rosterReview')?.remove();if(!bulkRows.length)return;const incoming=bulkRows.filter(r=>!r.error),school=$('#bulkSchool').value;const classes=new Set(incoming.map(r=>r.cls));const existing=db.students.filter(s=>s.role===role&&s.year===year&&s.school===school&&classes.has(s.cls));const warnings=rosterWarnings([...existing,...incoming]);if(!warnings.length)return;const box=document.createElement('div');box.id='rosterReview';box.className='workflow-advice';box.innerHTML='<strong>명단 확인 안내 · 등록을 막지 않습니다</strong><p>기존 학생과 이번 명단을 합쳐 확인했습니다. 전출 등으로 빈 번호가 있을 수 있습니다.</p>'+warnings.map(w=>'<p><b>'+esc(w.cls)+'</b>'+(w.gaps.length?' · 빈 번호: '+w.gaps.slice(0,30).join(', ')+(w.gaps.length>30?' 외 '+(w.gaps.length-30)+'개':''):'')+(w.names.length?' · 같은 이름: '+w.names.map(esc).join(', '):'')+'</p>').join('');$('#bulkRows').before(box);};
document.addEventListener('input',e=>{if(e.target.closest('#bulkModal'))$('#rosterReview')?.remove();});
document.addEventListener('change',e=>{if(e.target.closest('#bulkModal'))$('#rosterReview')?.remove();});

