if(resume&&['homeroom','subject'].includes(resume.role)&&db.years.includes(resume.year)&&menu.some(([p])=>p===resume.page)){
 role=resume.role;year=resume.year;page=resume.page;schoolFilter=srReadSchool(role);srRememberedRole=role;
 if((role==='homeroom'&&['assessments','subjectNotes'].includes(page))||(role==='subject'&&['tasks','notes'].includes(page)))page='dashboard';
}
